import{_ as a,a as o,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"MongoDB：文档、命名空间与连接","description":"BSON文档、命名空间与连接前置。","frontmatter":{"title":"MongoDB：文档、命名空间与连接","description":"BSON文档、命名空间与连接前置。","showdocs":{"topics":[{"id":"mongodb","title":"MongoDB","link":"/topics/mongodb/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"MongoDB 文档模型与一致性理论","summary":"BSON文档、命名空间与连接前置。","status":"active","related":[{"title":"MongoDB 操作与命令","link":"/middleware/databases/mongodb/plus/ecosystem/mongodb-general-general","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB 数据库与认证操作","link":"/middleware/databases/mongodb/plus/subjects/mongodb-index","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB：版本化任务完整 CLI","link":"/middleware/databases/mongodb/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"MongoDB 数据模型与配置","link":"/middleware/databases/mongodb/plus/subjects/mongodb-base-copy","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB：连接诊断、备份恢复与自检","link":"/middleware/databases/mongodb/operations","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":{"text":"MongoDB：模型、索引、原子性与一致性","link":"/middleware/databases/mongodb/base/intermediate/mechanisms"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"MongoDB：模型、索引、原子性与一致性","link":"/middleware/databases/mongodb/base/intermediate/mechanisms"}},"headers":[],"relativePath":"middleware/databases/mongodb/base/basic/start.md","filePath":"middleware/databases/mongodb/base/basic/start.md"}'),s={name:"middleware/databases/mongodb/base/basic/start.md"};function d(r,e,i,l,c,m){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="mongodb-文档、命名空间与连接" tabindex="-1">MongoDB：文档、命名空间与连接 <a class="header-anchor" href="#mongodb-文档、命名空间与连接" aria-label="Permalink to &quot;MongoDB：文档、命名空间与连接&quot;">​</a></h1><p>数据库保存可查询的持久数据。MongoDB 的数据库下面是集合，集合里面是文档；文档由字段和值组成，可以包含数组和内嵌文档。它不是“把所有 JSON 文件直接扔进一个目录”，仍需要设计模型、索引、权限和恢复策略。</p><p>本课面向 MongoDB Server 8.0 版本族、PyMongo 4.x（示例声明 &gt;=4.10,&lt;5）、独立安装的 mongosh 与 Database Tools。核对日期：2026-10-17，未承诺任意补丁和托管兼容实现相同。全部示例未执行，没有启动服务、连接账户或安装依赖。</p><h2 id="bson" tabindex="-1">BSON 与 JSON 的区别 <a class="header-anchor" href="#bson" aria-label="Permalink to &quot;BSON 与 JSON 的区别 {#bson}&quot;">​</a></h2><p>MongoDB BSON 是带类型的二进制文档表示，除 JSON 常见值外还有 ObjectId、日期、二进制、Decimal128 等。字符串 &quot;42&quot; 和数字 42 不相同，日期字符串也不会自动成为 BSON Date。本例主动使用字符串 _id，因此输出能被标准 JSON 编码；真实 ObjectId 需要 Extended JSON 或显式转换。<a href="https://www.mongodb.com/docs/manual/reference/bson-types/" target="_blank" rel="noopener noreferrer">官方 BSON 类型</a></p><p>一个文档有唯一 _id；集合普通情况下自动提供 _id 唯一索引。BSON 文档有 16 MiB 大小上限，不能把无限增长的事件历史或附件一直追加到同一个文档。金额应明确 Decimal128 或整数最小单位，避免浮点比较产生业务歧义。字段缺失与字段为 null 的语义也必须在查询时区分。</p><h2 id="namespace" tabindex="-1">命名空间与认证数据库 <a class="header-anchor" href="#namespace" aria-label="Permalink to &quot;命名空间与认证数据库 {#namespace}&quot;">​</a></h2><p>MongoDB authSource 指认证用户所在数据库，不等于保存业务文档的数据库。连接串的主机、目标数据库、authSource、replicaSet 和 TLS 共同表达连接意图。<code>use theory_tasks</code> 在 mongosh 中切换数据库上下文，不会单凭切换动作创建持久数据库；真正写入或显式建集合才涉及持久内容。<a href="https://www.mongodb.com/docs/mongodb-shell/connect/" target="_blank" rel="noopener noreferrer">官方连接说明</a></p><p>生产权限应限定到所需集合和操作，不能把开放 bindIp 当作可用性配置就结束；还要评估认证、网络和 TLS。SRV 连接依赖 DNS 和相应驱动能力，不代表已经认证成功。本文只解释配置，不提供默认云账户或远程目标。</p><h2 id="commands" tabindex="-1">mongosh 查询与写入 <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;mongosh 查询与写入 {#commands}&quot;">​</a></h2><p>MongoDB mongosh 使用 JavaScript 风格对象表达过滤器，find 返回游标，投影决定字段，sort 决定顺序，limit 限制数量。<code>db.tasks.find({status:&quot;open&quot;},{owner:1}).sort({_id:1}).limit(20)</code> 仍默认返回 _id。updateOne 的 <code>$set</code> 修改指定字段，替换整个文档是不同操作；deleteOne 则删除匹配的一条，过滤条件必须足够精确。<a href="https://www.mongodb.com/docs/mongodb-shell/crud/" target="_blank" rel="noopener noreferrer">官方 CRUD</a></p><p>原有命令入口仍保留；它们的占位字段需要读者替换为自己已批准的环境。本轮未运行任何 mongosh 命令。练习：为什么 find 不写 sort 无法承诺稳定第一页？解答：存储与执行计划没有替你规定业务排序，分页应使用明确且唯一的排序键。</p><h2 id="exercise" tabindex="-1">前置自检 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;前置自检 {#exercise}&quot;">​</a></h2><p>请把一条任务记录画成文档，写出 _id、owner、status 和 version 四个字段及各自类型。参考：字符串任务号、字符串所有者、有限状态字符串、非负整数版本。随后阅读<a href="/middleware/databases/mongodb/base/intermediate/mechanisms">模型与一致性</a>，解释把状态和版本放在同一文档如何帮助条件更新。</p>',14)])])}const p=a(s,[["render",d]]);export{b as __pageData,p as default};
